import pandas as pd

def clean(df):
    df = df.copy()
    df = df.drop_duplicates()
    if "Category" in df.columns:
        df["Category"] = df["Category"].astype("string").str.strip()
        df["Category"] = df["Category"].replace({"Furnture": "Furniture"})
    if "Region" in df.columns:
        df["Region"] = df["Region"].astype("string").str.strip()
        df["Region"] = df["Region"].replace({"": pd.NA})
    for col in ["Order_ID", "Quantity", "Price", "Revenue"]:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors="coerce")
    return df

def answer(df):
    d = clean(df)
    d = d[d["Category"].notna()]
    grouped = d.groupby("Category", dropna=True)["Price"].mean()
    return {str(label): float(value) for label, value in grouped.items()}
